"use client";

/**
 * Grid wipe transition: the next scene appears through a grid of tiles that
 * grow in a diagonal wave from the top-left corner. Use it to move between
 * sections of a structured story.
 *
 * Written by Better Design. A presentation for `<TransitionSeries.Transition>`,
 * plus `GridWipeDemo`, two theme-coloured cards that play it.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { linearTiming, TransitionSeries, type TransitionPresentation, type TransitionPresentationComponentProps } from "@remotion/transitions";
import { AbsoluteFill, Easing, useVideoConfig } from "remotion";
import { pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600"], subsets: ["latin"] });

export type GridWipeProps = {
  /** Tiles across the frame. */
  columns?: number;
  /** Tiles down the frame. */
  rows?: number;
  /** Share of the move spent staggering, 0 to 0.9. Higher reads as a wave. */
  stagger?: number;
};

function GridWipePresentation({ children, presentationDirection, presentationProgress: p, passedProps }: TransitionPresentationComponentProps<GridWipeProps>) {
  const { width, height } = useVideoConfig();
  const { columns = 8, rows = 5, stagger = 0.6 } = passedProps;
  if (presentationDirection === "exiting") return <AbsoluteFill>{children}</AbsoluteFill>;

  const tw = width / columns;
  const th = height / rows;
  const span = Math.max(1, columns + rows - 2);
  const parts: string[] = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < columns; c++) {
      const start = ((c + r) / span) * stagger;
      const local = Math.min(1, Math.max(0, (p - start) / (1 - stagger)));
      if (local <= 0) continue;
      const s = 1 - (1 - local) ** 3;
      // Each tile grows from its own centre, 2px oversize so finished tiles leave no seam.
      const w = (tw + 2) * s;
      const h = (th + 2) * s;
      const x = c * tw + (tw - w) / 2;
      const y = r * th + (th - h) / 2;
      parts.push(`M${x} ${y}h${w}v${h}h${-w}Z`);
    }
  }
  if (p >= 1) return <AbsoluteFill>{children}</AbsoluteFill>;
  return <AbsoluteFill style={{ clipPath: `path("${parts.join("") || "M0 0Z"}")` }}>{children}</AbsoluteFill>;
}

/** Reveal the next scene through a staggered grid of tiles. */
export function gridWipe(props: GridWipeProps = {}): TransitionPresentation<GridWipeProps> {
  return { component: GridWipePresentation, props };
}

export interface GridWipeDemoProps {
  /** Title on the first card. */
  fromTitle?: string;
  /** Title on the second card. */
  toTitle?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

function DemoCard({ title, step, ink, muted, surface, page, line, family }: { title: string; step: string; ink: string; muted: string; surface: string; page: string; line: string; family: string }) {
  return (
    <AbsoluteFill style={{ background: page, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div style={{ width: 1120, height: 600, borderRadius: 36, background: surface, border: `2px solid ${line}`, padding: 88, display: "flex", flexDirection: "column", justifyContent: "space-between" }}>
        <div style={{ fontSize: 30, fontWeight: 500, color: muted, letterSpacing: "0.02em" }}>{step}</div>
        <div style={{ fontSize: 112, fontWeight: 600, letterSpacing: "-0.04em", lineHeight: 1, color: ink }}>{title}</div>
        <div style={{ display: "flex", gap: 16 }}>
          <div style={{ width: 260, height: 18, borderRadius: 9, background: withAlpha(ink, 0.14) }} />
          <div style={{ width: 160, height: 18, borderRadius: 9, background: withAlpha(ink, 0.08) }} />
        </div>
      </div>
    </AbsoluteFill>
  );
}

/** Two cards with the transition between them, for the gallery. 78 frames. */
export function GridWipeDemo({ fromTitle = "Where it starts", toTitle = "Where it lands", theme: themeOverride, font }: GridWipeDemoProps) {
  const t = useVideoTheme(themeOverride);
  const family = pickFont(font, t, INTER);
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={44}>
        <DemoCard title={fromTitle} step="01" ink={t.cardForeground} muted={t.mutedForeground} surface={t.card} page={t.background} line={t.border} family={family} />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition presentation={gridWipe({ columns: 8, rows: 5 })} timing={linearTiming({ durationInFrames: 30, easing: Easing.bezier(0.65, 0, 0.35, 1) })} />
      <TransitionSeries.Sequence durationInFrames={64}>
        <DemoCard title={toTitle} step="02" ink={t.primaryForeground} muted={withAlpha(t.primaryForeground, 0.7)} surface={withAlpha(t.primaryForeground, 0.08)} page={t.primary} line={withAlpha(t.primaryForeground, 0.22)} family={family} />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
}
